size_t collect_active_users(const User *users, size_t length, time_t cutoff, char **names) {
    size_t count = 0;

    for (size_t index = 0; index < length; index++) {
        if (!users[index].is_online || users[index].last_seen_at <= cutoff) {
            continue;
        }

        names[count++] = users[index].name;
    }

    return count;
}

int clamp_score(int score, int minimum, int maximum) {
    if (score < minimum) {
        return minimum;
    }

    if (score > maximum) {
        return maximum;
    }

    return score;
}

bool build_summary(const Project *project, char *buffer, size_t capacity) {
    if (project->name[0] == '\0') {
        return false;
    }

    int written = snprintf(buffer, capacity, "%s:%s", project->name, project->branch);
    return written >= 0 && (size_t)written < capacity;
}

int compare_scores_desc(const void *left, const void *right) {
    const ScoreEntry *a = left;
    const ScoreEntry *b = right;

    return b->score - a->score;
}

void top_scores(ScoreEntry *entries, size_t length) {
    qsort(entries, length, sizeof(ScoreEntry), compare_scores_desc);
}

size_t group_posts_by_tag(const Post *posts, size_t length, TagGroup *groups) {
    size_t group_count = 0;

    for (size_t index = 0; index < length; index++) {
        for (size_t tag = 0; tag < posts[index].tag_count; tag++) {
            group_count = append_tag(groups, group_count, posts[index].tags[tag], posts[index].slug);
        }
    }

    return group_count;
}

ScoreEntry *pick_best(ScoreEntry *entries, size_t length) {
    if (length == 0) {
        return NULL;
    }

    ScoreEntry *best = &entries[0];
    for (size_t index = 1; index < length; index++) {
        if (entries[index].score > best->score) {
            best = &entries[index];
        }
    }

    return best;
}

RouteLanguage get_route_language(const char *value) {
    if (strcmp(value, "c") == 0) {
        return ROUTE_LANGUAGE_C;
    }

    if (strcmp(value, "cpp") == 0) {
        return ROUTE_LANGUAGE_CPP;
    }

    return ROUTE_LANGUAGE_JAVASCRIPT;
}

size_t normalize_values(char **values, size_t length) {
    size_t write_index = 0;

    for (size_t index = 0; index < length; index++) {
        trim_in_place(values[index]);
        if (values[index][0] != '\0') {
            values[write_index++] = values[index];
        }
    }

    return write_index;
}

const char *primary_email(const User *user) {
    for (size_t index = 0; index < user->contact_count; index++) {
        ContactMethod method = user->contacts[index];

        if (method.kind == CONTACT_EMAIL && method.is_verified) {
            return method.value;
        }
    }

    return NULL;
}

bool read_first_line(FILE *file, char *buffer, size_t capacity) {
    if (fgets(buffer, capacity, file) == NULL) {
        return false;
    }

    buffer[strcspn(buffer, "\n")] = '\0';
    return buffer[0] != '\0';
}
